<script>
 import {directoryUtilityWindow,directoryUtilityCapabilities,directoryUtilityAuthorized,directoryUtilityRecords,directorySearchNodes,directoryUtilityMenus} from './directory-utility.js';
 import {createIdentityView} from './identity-assistant-core.js';
 import './identity-assistants.css';
 let {state: directoryUtilityState,profile,window:actualWindow=null,windowId=actualWindow?.id,preferences=null,sceneSession=null,execute,registerView=()=>()=>{},available=true,active=true,controls={},showMenuBar=false}=$props();
 let root=$state(null),error=$state(''),passcode=$state(''),name=$state(''),groupName=$state(''),members=$state([]),policyMode=$state('local'),paths=$state(['local']),linkUserId=$state('');
 const session=$derived(directoryUtilityWindow(directoryUtilityState,windowId)),cap=$derived(directoryUtilityCapabilities(profile)),authorized=$derived(!!session&&!!preferences&&!!sceneSession&&directoryUtilityAuthorized(session,preferences,sceneSession)),records=$derived(session?directoryUtilityRecords(directoryUtilityState,session,sceneSession):[]),selected=$derived(records.find(r=>r.id===session?.selectedId)),server=$derived(directoryUtilityState.servers.find(s=>s.id===session?.selectedServerId)),menus=$derived(directoryUtilityMenus({session,authorized,classic:cap.classic}));
 async function run(suffix,payload={}){if(!root?.isConnected||!available||!active)return;const original=session,mounted=root;const result=await execute('directoryutility.'+suffix,{windowId},payload);if(root===mounted&&session===original)error=result?.status==='rejected'?result.error?.message??'Operation unavailable.':'';return result;}
 async function menu(item){if(!item.enabled)return;await run('menu',{menu:null});await run(item.request.command.slice(17),item.request.payload);}
 function move(index,delta){if(index===0||index+delta<=0||index+delta>=paths.length)return;const next=[...paths];[next[index],next[index+delta]]=[next[index+delta],next[index]];paths=next;}
 $effect(()=>{if(!root||!session)return;const view=createIdentityView({root,getRoot:()=>root,getSession:()=>directoryUtilityWindow(directoryUtilityState,windowId),available:()=>available&&active});const remove=registerView(windowId,view);return ()=>{view.dispose();if(typeof remove==='function')remove();else registerView(windowId,null,view);};});
 $effect(()=>{const p=directoryUtilityState.searchPolicy[session?.policy??'authentication'];policyMode=p.mode;paths=[...p.paths];});
 $effect(()=>{const panel=session?.panel;passcode='';if(panel==='user')name=selected?.name??'';if(panel==='group'){groupName=session.recordType==='groups'?selected?.name??'':'';members=session.recordType==='groups'?[...(selected?.memberUserIds??[])]:[];}});
 const tabs=[['services','Services'],['search','Search Policy'],['editor','Directory Editor']];
</script>
{#if session}<section bind:this={root} class="identity-native directory-native" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} aria-label={cap.label}>
 {#if cap.windows||showMenuBar}<nav class="identity-menubar" aria-label="Application menus">{#each menus as m}<button data-identity-control={'menu-'+m.id} class:chosen={session.menu===m.id} onclick={()=>run('menu',{menu:session.menu===m.id?null:m.id})}>{m.label}</button>{/each}</nav>{/if}{#if session.menu}<div class="identity-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.children??[] as item}<button role="menuitem" disabled={!item.enabled} onclick={()=>menu(item)}>{item.label}</button>{/each}</div>{/if}
 <nav class="directory-tabs" aria-label="Directory panes">{#each tabs as t}<button data-identity-control={'tab-'+t[0]} class:chosen={session.tab===t[0]} onclick={()=>run('navigate',{tab:t[0]})}>{t[1]}</button>{/each}{#if cap.classic}<button data-identity-control="tab-connect" class:chosen={session.tab==='connect'} onclick={()=>run('navigate',{tab:'connect'})}>Connect · Local</button>{/if}</nav>
 <main class="directory-content">{#if session.tab==='services'}<p>Select a directory service to configure. These are authored local configurations, not discovered servers.</p><div class="directory-table"><div class="directory-row heading"><span>On</span><span>Service</span><span>Server</span><span>Local State</span></div>{#each directoryUtilityState.servers as s}<div class="directory-row"><input data-identity-control={'enabled-'+s.id} aria-label={'Enable '+s.name} type="checkbox" checked={s.enabled} disabled={!authorized||s.bound} onchange={e=>run('service',{operation:e.currentTarget.checked?'enable':'disable',serverId:s.id})}/><button data-identity-control={'service-'+s.id} class:chosen={server===s} onclick={()=>run('navigate',{selectedServerId:s.id})}>{s.kind==='ldap'?'LDAPv3':'Active Directory'} · {s.name}</button><span>{s.host}</span><span>{s.bound?'Bound locally':'Unbound'}</span></div>{/each}{#if !directoryUtilityState.servers.length}<p class="identity-empty">No authored directory services. Add an LDAPv3 or Active Directory configuration.</p>{/if}</div><div class="identity-actions"><button data-identity-control="add-ldap" disabled={!authorized} onclick={()=>run('stage',{kind:'ldap'})}>＋ LDAPv3</button><button data-identity-control="add-ad" disabled={!authorized} onclick={()=>run('stage',{kind:'ad'})}>＋ Active Directory</button><button data-identity-control="edit-service" disabled={!authorized||!server} onclick={()=>run('stage',{serverId:server.id})}>Edit…</button><button data-identity-control="remove-service" disabled={!authorized||!server} onclick={()=>run('service',{operation:'remove',serverId:server.id})}>−</button></div>{#if server}<dl><dt>Directory node</dt><dd>/{server.kind==='ad'?'Active Directory':'LDAPv3'}/{server.host}</dd><dt>Original network service</dt><dd>{server.networkServiceId}</dd><dt>Computer ID</dt><dd>{server.computerId||'—'}</dd><dt>Search Base</dt><dd>{server.baseDN||'—'}</dd><dt>Bound original user ID</dt><dd>{server.boundUserId??'—'}</dd></dl><button data-identity-control="bind" disabled={!authorized} onclick={()=>run('service',{operation:server.bound?'unbind':'bind',serverId:server.id})}>{server.bound?'Unbind Local Configuration':'Bind Local Configuration'}</button><p>This commits a local authored binding record using the original scene administrator. No LDAP/AD transport or host enrollment occurs.</p>{/if}
 {:else if session.tab==='search'}<nav class="identity-actions">{#each [['authentication','Authentication'],['contacts','Contacts']] as p}<button data-identity-control={'policy-'+p[0]} class:chosen={session.policy===p[0]} onclick={()=>run('navigate',{policy:p[0]})}>{p[1]}</button>{/each}</nav><label>Search Path<select data-identity-control="policy-mode" bind:value={policyMode} disabled={!authorized}><option value="automatic">Automatic · bound local nodes</option><option value="custom">Custom path</option><option value="local">Local directory</option></select></label><p>Applied nodes: {directorySearchNodes(directoryUtilityState,session.policy).map(id=>id==='local'?'/Local/Default':directoryUtilityState.servers.find(s=>s.id===id)?.name??id).join(' → ')}</p><div class="directory-table">{#each paths as id,index}<div class="policy-path"><span>{id==='local'?'/Local/Default':directoryUtilityState.servers.find(s=>s.id===id)?.name??id}</span><button aria-label="Move path up" disabled={!authorized||index<2} onclick={()=>move(index,-1)}>↑</button><button aria-label="Move path down" disabled={!authorized||index===0||index===paths.length-1} onclick={()=>move(index,1)}>↓</button><button aria-label="Remove path" disabled={!authorized||index===0} onclick={()=>paths=paths.filter(x=>x!==id)}>−</button></div>{/each}</div><label>Add Bound Local Directory<select data-identity-control="policy-add" disabled={!authorized} value="" onchange={e=>{if(e.currentTarget.value&&!paths.includes(e.currentTarget.value))paths=[...paths,e.currentTarget.value];}}><option value="">Choose directory…</option>{#each directoryUtilityState.servers.filter(s=>s.bound&&s.enabled&&!paths.includes(s.id)) as s}<option value={s.id}>{s.name}</option>{/each}</select></label><button data-identity-control="policy-apply" disabled={!authorized} onclick={()=>run('policy',{policy:session.policy,mode:policyMode,paths})}>Apply</button><p>Local directory search configuration only. No OS login policy, Contacts account or DHCP-supplied trust is changed.</p>
 {:else if session.tab==='editor'}<div class="identity-actions"><label>Viewing<select data-identity-control="record-type" value={session.recordType} onchange={e=>run('navigate',{recordType:e.currentTarget.value})}><option value="users">Users · Original Scene</option><option value="groups">Groups · Local Directory</option></select></label><label>in node<select data-identity-control="node" value={session.nodeId} onchange={e=>run('navigate',{nodeId:e.currentTarget.value})}><option value="local">/Local/Default</option>{#each directoryUtilityState.servers as s}<option value={s.id}>/{s.kind==='ad'?'Active Directory':'LDAPv3'}/{s.host}</option>{/each}</select></label><label>Search<input data-identity-control="record-search" type="search" value={session.search} oninput={e=>run('navigate',{search:e.currentTarget.value})}/></label></div><div class="directory-editor"><div class="directory-records">{#each records as record}<button data-identity-control={'record-'+record.id} class:chosen={record===selected} onclick={()=>run('navigate',{selectedId:record.id})}>{record.name}</button>{/each}{#if !records.length}<p>No matching local records.</p>{/if}</div><div class="directory-attributes">{#if selected}<h3>Native field projection · same source ID</h3><dl><dt>RecordName</dt><dd>{selected.id}</dd><dt>FullName</dt><dd>{selected.name}</dd>{#if session.recordType==='users'}<dt>SceneUserKind</dt><dd>{selected.kind}</dd><dt>SceneLocked</dt><dd>{selected.locked?'True':'False'}</dd><dt>AuthenticationAuthority</dt><dd>Original scene credential verifier · no host credential exposed</dd>{:else}<dt>GroupMembership</dt><dd>{selected.memberUserIds.map(id=>sceneSession?.users.find(u=>u.id===id)?.name??id).join(', ')||'Empty group'}</dd>{/if}</dl><p>UniqueID, GUID, home directory and shell are not fabricated: the original source does not contain these attributes.</p><div class="identity-actions"><button data-identity-control="edit-record" disabled={!authorized} onclick={()=>run('panel',{panel:session.recordType==='users'?'user':'group'})}>Edit…</button>{#if session.recordType==='users'}<button data-identity-control="lock-user" disabled={!authorized||selected.id===sceneSession.activeUserId||selected.kind!=='local'} onclick={()=>run('user',{operation:selected.locked?'unlock':'lock',userId:selected.id})}>{selected.locked?'Unlock User':'Lock User'}</button>{:else}<button data-identity-control="delete-group" disabled={!authorized} onclick={()=>run('group',{operation:'delete',groupId:selected.id})}>Delete Group</button>{/if}</div>{:else}<p>Select a real local record to inspect its source fields.</p>{/if}</div></div><div class="identity-actions"><button data-identity-control="add-user" disabled={!authorized} onclick={async()=>{await run('navigate',{selectedId:null,recordType:'users',nodeId:'local'});await run('panel',{panel:'user'});}}>＋ User</button><button data-identity-control="add-group" disabled={!authorized} onclick={async()=>{await run('navigate',{selectedId:null,recordType:'groups'});await run('panel',{panel:'group'});}}>＋ Group</button><button data-identity-control="export-directory" disabled={!authorized} onclick={()=>run('export')}>Export LDIF</button></div>{#if session.nodeId!=='local'}<label>Link Original Scene User<select data-identity-control="link-user" bind:value={linkUserId}><option value="">Choose original user…</option>{#each sceneSession?.users??[] as u}<option value={u.id}>{u.name} ({u.id})</option>{/each}</select></label><button data-identity-control="link-confirm" disabled={!authorized||!linkUserId} onclick={()=>run('user',{operation:'link',serverId:session.nodeId,userId:linkUserId})}>Link Record ID to Local Node</button><button data-identity-control="unlink" disabled={!authorized||!selected||session.recordType!=='users'} onclick={()=>run('user',{operation:'unlink',serverId:session.nodeId,userId:selected.id})}>Unlink Selected ID</button>{/if}
 {:else}<h2>Connect · Local Server Inspector</h2><p>Historical Directory Utility could administer macOS Server remotely. This counterpart inspects authored local configurations only; remote administration is not claimed.</p>{#each directoryUtilityState.servers as s}<div class="policy-path"><span>{s.name} · {s.host} · {s.bound?'Bound locally':'Unbound'}</span><button data-identity-control={'connect-'+s.id} onclick={()=>run('navigate',{tab:'services',selectedServerId:s.id})}>Inspect</button></div>{/each}{#if !directoryUtilityState.servers.length}<button data-identity-control="connect-create" disabled={!authorized} onclick={()=>run('stage',{kind:'ldap'})}>Create Local LDAPv3 Record</button>{/if}{/if}</main>
 <div class="directory-lock identity-toolbar"><button data-identity-control="lock" onclick={()=>run(authorized?'lock':'panel',authorized?{}:{panel:'authenticate'})}>{authorized?'🔓':'🔒'}</button><p>{authorized?'Click the lock to prevent local changes.':'Click the lock to make changes using the original scene administrator.'}</p></div><footer><span role="status">{error||session.status}</span><details><summary>Local scope</summary><p>{cap.disclosure}</p></details></footer>
 {#if session.panel!=='none'}<div class="identity-backdrop"><section class="identity-sheet" role="dialog" aria-modal="true" aria-label={session.panel}><header><h2>{session.panel==='authenticate'?'Directory Utility Authorization':session.panel==='server'?'Directory Service Configuration':session.panel==='user'?'Original Scene User':session.panel==='group'?'Local Directory Group':'About Directory Utility'}</h2><button data-identity-control="sheet-close" onclick={()=>run('panel',{panel:'none'})}>×</button></header>
 {#if session.panel==='authenticate'}<p>Use the current fictional administrator’s scene passcode (initially scene). Never enter real credentials.</p><label>Scene passcode<input data-identity-control="passcode" type="password" bind:value={passcode} maxlength="128"/></label><button data-identity-control="authorize" onclick={async()=>{await run('authenticate',{passcode});passcode='';}}>Modify Configuration</button>
 {:else if session.panel==='server'&&session.draft&&authorized}<p>{session.draft.kind==='ad'?'Active Directory':'LDAPv3'} · staged local configuration</p>{#each [['name','Configuration Name',128],['host','Server (.invalid)',256],['baseDN','Search Base',512],['computerId','Computer ID',128]] as field}<label>{field[1]}<input data-identity-control={'draft-'+field[0]} maxlength={field[2]} value={session.draft[field[0]]} onchange={e=>run('draft',{[field[0]]:e.currentTarget.value})}/></label>{/each}<label>Original Network Service<select data-identity-control="network-service" value={session.draft.networkServiceId} onchange={e=>run('draft',{networkServiceId:e.currentTarget.value})}>{#each preferences?.configuration.network.services??[] as s}<option value={s.id}>{s.kind} · {s.enabled?'Enabled':'Disabled'}</option>{/each}</select></label><label class="identity-check"><input data-identity-control="ssl" type="checkbox" checked={session.draft.ssl} onchange={e=>run('draft',{ssl:e.currentTarget.checked})}/>Encrypt using SSL · authored setting, no transport</label><label class="identity-check"><input data-identity-control="enabled" type="checkbox" checked={session.draft.enabled} onchange={e=>run('draft',{enabled:e.currentTarget.checked})}/>Enable local service configuration</label><button data-identity-control="service-save" onclick={()=>run('save')}>Apply</button>
 {:else if session.panel==='user'&&authorized}<p>{selected?'Edits the original session user, not a directory copy.':'Creates one actual fictional user in the original session source.'}</p><label>Full Name<input data-identity-control="user-name" bind:value={name} maxlength="128"/></label><button data-identity-control="user-save" onclick={()=>run('user',{operation:selected?'rename':'create',...(selected?{userId:selected.id}:{}),name})}>Save Original User</button>
 {:else if session.panel==='group'&&authorized}<label>Group Name<input data-identity-control="group-name" bind:value={groupName} maxlength="128"/></label><fieldset><legend>Original user IDs</legend>{#each sceneSession?.users??[] as u}<label class="identity-check"><input data-identity-control={'member-'+u.id} type="checkbox" checked={members.includes(u.id)} onchange={e=>members=e.currentTarget.checked?[...members,u.id]:members.filter(id=>id!==u.id)}/>{u.name} · {u.id}</label>{/each}</fieldset><button data-identity-control="group-save" onclick={()=>run('group',{operation:selected&&session.recordType==='groups'?'update':'create',...(selected&&session.recordType==='groups'?{groupId:selected.id}:{}),name:groupName,memberUserIds:members,nodeId:session.nodeId})}>Save Group</button>{:else}<p>{cap.disclosure}</p>{/if}{#if error}<p class="identity-error" role="alert">{error}</p>{/if}</section></div>{/if}
</section>{/if}
